package mrpapermoon.whisper.service.internalimport com.google.android.gms.nearby.connection.Payloadinternal class BytesPayloadCallback : FlowPayloadCallback() {	override fun onPayloadReceived(		endpointId: String,		payload: Payload,	) {		super.onPayloadReceived(endpointId, payload)		when (payload.type) {			Payload.Type.BYTES -> {				emitEvent(Event.OnBytesPayloadReceived(payload.asBytes()!!))			}			else -> {				emitEvent(Event.OnUnsupportedPayloadReceived())			}		}	}}